/**
 * アルゼンチンのクイズ。
 *
 * 難易度1〜10。基準は他の盤面と同じ「その国の外にいる一般的な人が
 * どれくらい答えられそうか」。都市カードに書いた事実(レティーロの3駅構造・
 * ロサリオの大豆輸出・サンアントニオ・デ・ロス・コブレスの高架橋・
 * エスケルとインヘニエロ・ハコバッシのラ・トロチータ・トゥクマンの独立史跡と
 * 製糖業・エル・ファミリアルの伝承・ヤシレタダムの腐敗疑惑・メンドーサとサン
 * フアンの地震・マラルグエのESA局・コモドロ・リバダビアの石油発見と
 * YPF設立年など)は、原則として**そのままでは問わない**。関連するが
 * 別の角度・別の数字の事実を選んでいる。
 *
 * 南アメリカ盤(タンゴの起源・ガウチョ/パンパの語源・アコンカグア・
 * サンマルティンの1817年アンデス越え・プーマ/ジャガーの語源・グアナコ・
 * チャコ戦争の同盟国)、世界一周盤(世界最長の陸の国境=カナダ/米国、
 * 選択肢にアルゼンチン/チリが出るが正解ではない)とは重ならないよう選んだ。
 * 並行して書かれているチリ盤(アンデス越え・移民・ワイン)とも、
 * 「アンデス越えの鉄道」「ワイン産業の隆盛」そのものを主題にする問いは避けた。
 *
 * 難易度9〜10は1問ずつ裏取りの確度をコメントに書いた。
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

